options.css:
:host { color-scheme:dark; }
* { box-sizing:border-box; }
.ai { --accent:#84ddca; --violet:#b5a0ff; --amber:#ecc78d; --red:#f09584; --muted:#91a7b4; width:100%; height:100%; overflow:auto; container-type:inline-size; padding:0 26px 24px; background:radial-gradient(ellipse at 90% 0%,#192532 0,transparent 44%),#0e151d; color:#e8eeed; font:13px/1.5 Arial,Helvetica,sans-serif; }
.ai.cluster { --accent:#b5a0ff; }.ai.chassis { --accent:#ecc78d; }
.mast { min-height:72px; display:flex; align-items:center; justify-content:space-between; gap:14px; border-bottom:1px solid #2d3c47; }
.brand { display:flex; gap:13px; align-items:center; }.brand b { font:44px Georgia,serif; color:var(--accent); letter-spacing:-5px; padding-right:5px; }.brand strong { display:block; font-size:12px; letter-spacing:.13em; }.brand small { font:9px monospace; letter-spacing:.1em; color:var(--muted); }
.source { display:flex; align-items:flex-end; flex-direction:column; gap:5px; }.badge { border:1px solid #6a5b44; color:#ecc78d; padding:4px 8px; font:9px monospace; letter-spacing:.09em; white-space:nowrap; }.freshness { color:var(--muted); font:10px monospace; }.freshness::before { content:'●'; color:var(--accent); margin-right:5px; }
.hero { display:flex; align-items:flex-end; justify-content:space-between; gap:18px; padding:25px 0 22px; }.eyebrow { color:var(--muted); font:10px/1.5 monospace; letter-spacing:.12em; margin:0 0 6px; }h1 { font:clamp(32px,4.2cqw,57px)/1.03 Georgia,serif; font-weight:400; letter-spacing:-.035em; margin:0; }h1 em { color:var(--accent); } .subtitle { font-size:12px; color:var(--muted); margin:10px 0 0; max-width:640px; }
button,a { -webkit-tap-highlight-color:transparent; }button { cursor:pointer; font:inherit; }button:focus-visible,a:focus-visible,[role=button]:focus-visible { outline:2px solid #edf3d9; outline-offset:4px; }.quiet { background:transparent; color:#c1d2d8; border:1px solid #3f5562; padding:8px 11px; font-size:10px; white-space:nowrap; }.quiet:hover { border-color:var(--accent); }
.kpis { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); border-block:1px solid #34444e; }.kpi { padding:16px 16px 15px; border-right:1px solid #2c3b44; min-width:0; }.kpi:first-child { padding-left:0; }.kpi:last-child { border-right:0; }.kpi>span { display:block; font:9px monospace; color:var(--muted); letter-spacing:.05em; }.kpi strong { font:38px/1.2 Georgia,serif; letter-spacing:-.045em; font-weight:400; }.kpi small { color:var(--muted); margin-left:6px; font-size:11px; }.kpi p { color:var(--muted); font-size:10px; margin:3px 0 0; }.kpi svg { width:100%; height:25px; display:block; margin-top:3px; }.kpi path { fill:none; stroke:var(--accent); stroke-width:1.6; vector-effect:non-scaling-stroke; opacity:.65; }
.section-bar { display:flex; gap:12px; align-items:center; justify-content:space-between; padding:22px 0 12px; }.section-bar h2 { font:13px monospace; letter-spacing:.07em; margin:0; }.section-bar p { color:var(--muted); font-size:10px; margin:4px 0 0; }
.visual { min-width:0; position:relative; border:1px solid #2a3a46; background:linear-gradient(140deg,#17233066,#0b121a99); border-radius:6px; overflow:hidden; }.visual>svg { display:block; width:100%; height:auto; }.scene { fill:none; }.svg-title { fill:#e0e9e8; font:22px monospace; letter-spacing:1px; }.svg-label { fill:#99afbb; font:16px monospace; }.svg-value { fill:#e5f1ec; font:32px Georgia,serif; }.svg-mini { fill:#8fa5b2; font:13px monospace; }.svg-accent { fill:var(--accent); }.hardware { fill:#15232f; stroke:#425967; stroke-width:1.5; }.hardware-top { fill:#213642; stroke:#526a75; stroke-width:1; }.board { fill:#101c25; stroke:#3d525e; stroke-width:2; }.selectable { cursor:pointer; outline:none; }.selectable .outline { stroke:#425969; stroke-width:1.5; }.selectable:hover .outline { stroke:var(--accent); }.selectable.selected .outline { stroke:#e7eacc; stroke-width:3; }.selectable.selected { filter:drop-shadow(0 0 8px #77d8c922); }.status-dot { fill:var(--accent); }.warning .status-dot,.degraded .status-dot { fill:var(--amber); }.failed .status-dot { fill:var(--red); }
.flow { fill:none; stroke:#78cfc9; stroke-width:3; stroke-dasharray:8 14; animation:flow var(--flow-speed,2s) linear infinite; opacity:.8; }.flow.fabric { stroke:var(--violet); stroke-width:3.5; }.flow.management { stroke:var(--amber); stroke-width:2.5; stroke-dasharray:3 9; opacity:.7; }.flow.air { stroke:#70abbd; stroke-dasharray:12 24; opacity:.25; }.flow.power { stroke:var(--accent); opacity:.45; }.link-base { stroke:#293e4b; stroke-width:7; fill:none; }.signal { animation:signal var(--activity,1.4s) ease-in-out infinite; }.rotor { animation:rotate var(--spin,.8s) linear infinite; transform-box:fill-box; transform-origin:center; }.failed .rotor { animation:none!important; opacity:.4; }.failed .fan-housing { stroke:var(--red); }.pulse { animation:signal 2s ease-in-out infinite; }
@keyframes flow { to { stroke-dashoffset:-44; } }@keyframes signal { 0%,100% { opacity:.35; }45% { opacity:1; }65% { opacity:.65; } }@keyframes rotate { to { transform:rotate(360deg); } }
.legend { display:flex; flex-wrap:wrap; gap:15px; color:var(--muted); font:10px monospace; padding:12px 0; }.legend span { display:flex; align-items:center; gap:6px; }.legend i { display:inline-block; width:18px; height:2px; background:var(--accent); }.legend i.violet { background:var(--violet); }.legend i.amber { background:var(--amber); }.legend i.red { background:var(--red); }.legend .dotted { background:repeating-linear-gradient(90deg,var(--amber) 0 3px,transparent 3px 5px); }
.detail { padding:18px; background:#14202a99; border:1px solid #334653; border-radius:6px; min-width:0; }.detail-head { display:flex; justify-content:space-between; align-items:center; gap:10px; }.detail-head h2 { font:30px Georgia,serif; margin:0; font-weight:400; letter-spacing:-.02em; }.pill { font:9px monospace; color:var(--accent); border:1px solid #45685f; border-radius:20px; padding:4px 8px; white-space:nowrap; }.pill.degraded,.pill.warm { color:var(--amber); border-color:#8b704e; }.pill.failed { color:var(--red); border-color:#a8685a; }.detail p { color:var(--muted); font-size:11px; margin:8px 0 12px; }.detail-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:13px; }.readout { border-bottom:1px solid #2b404c; padding-bottom:10px; }.readout span { display:block; font:9px monospace; color:var(--muted); }.readout strong { display:block; font:25px/1.4 Georgia,serif; font-weight:400; }.readout small { color:var(--muted); font-size:10px; }.bar { height:3px; background:#293e4b; margin-top:8px; }.bar i { display:block; height:100%; background:var(--accent); transition:width .5s; }
.gpu-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:7px; }.gpu-tile { background:#192c37; border:1px solid #39545c; border-radius:4px; padding:10px 8px; color:#c8e8e0; text-align:left; min-width:0; position:relative; overflow:hidden; }.gpu-tile:before { content:''; position:absolute; width:3px; top:0; bottom:0; left:0; background:var(--gpu-color,#84ddca); }.gpu-tile span { display:block; font:10px monospace; color:#aec4cb; }.gpu-tile strong { display:block; font:24px Georgia,serif; margin:5px 0; }.gpu-tile small { font:10px monospace; color:var(--muted); }.gpu-tile.warm { border-color:#9a7256; --gpu-color:#edbf83; }.gpu-tile[aria-pressed=true] { outline:2px solid #e4e5cc; outline-offset:1px; }.gpu-detail { font:11px/1.7 monospace; color:#a2bbc3; margin-top:12px; min-height:40px; }
.notice { padding:11px 13px; border-left:2px solid var(--amber); background:#75533117; color:#d1bfa1; font-size:11px; margin-top:15px; }.notice.failed { border-color:var(--red); background:#84432b17; color:#e9b6a9; }
.switches { display:flex; flex-wrap:wrap; gap:5px; }.switches button { background:transparent; border:1px solid #3b4e5b; color:var(--muted); padding:6px 10px; font-size:10px; }.switches button[aria-pressed=true] { background:#2b3e4c; color:#e7efed; border-color:#758b91; }
.nav { display:flex; flex-wrap:wrap; gap:8px; margin-top:18px; border-top:1px solid #2c3d47; padding-top:15px; }.nav a { color:var(--accent); border:1px solid #3b5260; text-decoration:none; font-size:11px; padding:7px 10px; }.nav a:hover { background:#293f4c; }.nav a.active { background:#233742; color:#eef0db; }
.ai footer { display:flex; flex-wrap:wrap; justify-content:space-between; gap:8px; color:#819ba7; font:9px/1.6 monospace; border-top:1px solid #2c3d47; padding-top:13px; margin-top:17px; letter-spacing:.035em; }
.ai.paused *,.ai.stale *,.ai.waiting * { animation-play-state:paused!important; }.ai.stale .freshness { color:var(--red); }.ai.stale .freshness:before { color:var(--red); }.ai.waiting .visual { opacity:.55; }.ai .empty { display:none; margin:14px 0; padding:12px; border:1px solid #625445; color:var(--amber); }.ai.waiting .empty { display:block; }
@container (max-width:700px) { .hero { align-items:center; }h1 { font-size:34px; }.kpi { padding-inline:11px; }.kpi strong { font-size:29px; }.kpi>span { font-size:8px; }.source { gap:5px; }.section-bar { flex-wrap:wrap; }.detail-grid { gap:10px; } }
@container (max-width:440px) { .mast { flex-wrap:wrap; padding-block:14px; }.brand strong { font-size:10px; }.source { flex-direction:row; align-items:center; }.hero { flex-wrap:wrap; }.kpis { grid-template-columns:repeat(2,minmax(0,1fr)); }.kpi:nth-child(2) { border-right:0; }.kpi:nth-child(3) { padding-left:0; }.kpi:nth-child(-n+2) { border-bottom:1px solid #2c3b44; }.gpu-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media (prefers-reduced-motion:reduce) { .ai * { animation-duration:0s!important; transition:none!important; } }

/* Keep the hardware scene prominent at common desktop heights. */
.mast { min-height:58px; }.hero { padding:17px 0; }h1 { font-size:clamp(30px,3.8cqw,47px); }.kpi { padding-block:12px; }.kpi strong { font-size:34px; }.kpi svg { height:19px; }.section-bar { padding-top:18px; }

.chassis .flow:not(.fabric):not(.management):not(.air) { stroke:#84ddca; }.chassis.plane-management .data-plane { opacity:.1; }.chassis.plane-data .management-plane { opacity:.08; }.fan-wall { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:9px; }.fan-card { background:#15232d; border:1px solid #425b62; border-radius:5px; color:#cfe4dc; text-align:center; padding:10px 6px; min-width:0; }.fan-card>span { display:block; font:12px monospace; }.fan-card svg { width:100%; max-width:90px; display:block; margin:auto; }.fan-card strong { display:block; font:25px Georgia,serif; font-weight:400; }.fan-card small { color:#96b1b8; font:9px monospace; }.fan-card>i { display:block; font:9px monospace; color:#8acbb9; margin-top:5px; }.fan-card.failed { background:#35231f; border-color:#a16e5f; color:#f0ac99; }.fan-card.failed>i { color:var(--red); }.fan-card[aria-pressed=true] { outline:2px solid #e7dcba; outline-offset:2px; }.component-detail { margin-top:20px; }.component-metrics { display:flex; flex-wrap:wrap; gap:25px; padding:13px 0 2px; }.component-metrics>div { min-width:90px; }.component-metrics span { display:block; font:9px monospace; color:var(--muted); }.component-metrics strong { font:27px Georgia,serif; font-weight:400; }.component-detail p { margin-bottom:0; }@container (max-width:600px) { .fan-wall { grid-template-columns:repeat(3,minmax(0,1fr)); }.fan-card svg { max-width:75px; } }

.chassis .legend i:not(.violet):not(.dotted) { background:#84ddca; }.fan-card.failed .rotor path { fill:#f09584; }

.chassis-layout { display:grid; grid-template-columns:minmax(0,3.5fr) minmax(225px,1fr); gap:18px; align-items:start; }.cooling-panel .section-bar { padding-top:0; align-items:start; flex-wrap:wrap; gap:7px; }.cooling-panel .fan-wall { grid-template-columns:repeat(2,minmax(0,1fr)); }.cooling-panel .fan-card svg { max-width:74px; }.cooling-panel .fan-card strong { font-size:25px; }.cooling-panel .fan-card { padding:8px 4px; }@container (max-width:900px) { .chassis-layout { grid-template-columns:1fr; }.cooling-panel .fan-wall { grid-template-columns:repeat(3,minmax(0,1fr)); } }

